mapper.select:
select eim.id, eim.supplier_id,eism.supplier_name,eim.intf_no,eim.intf_name,eim.intf_request_type,eim.intf_path,eim.intf_structure,
eim.intf_type_name,eim.intf_request_type,eim.intf_time_out,eim.intf_status,eim.intf_desc,eim.refer_intf_no,eim.refer_intf_status,
eim.async_save,eim.battle_flag,eim.battle_report_content,eim.before_handler,eim.input_time,eim.input_user_name,eim.update_user_id,eim.update_user_name
from ext_intf_manage eim left join ext_intf_supplier_manage eism
on eim.supplier_id = eism.supplier_id



	  and eim.supplier_id like #{supplierId}



	  and eism.supplier_name like #{supplierName}



	  and eim.intf_no like #{intfNo}



	  and eim.intf_name like #{intfName}


order by eim.input_time desc
